struct Point {
    int x, y;
};

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    cin >> n;

    const int total = 4 * n + 1;
    vector<Point> points(total);

    int minX = INT_MAX, maxX = INT_MIN;
    int minY = INT_MAX, maxY = INT_MIN;

    for (Point& p : points) {
        cin >> p.x >> p.y;
        minX = min(minX, p.x);
        maxX = max(maxX, p.x);
        minY = min(minY, p.y);
        maxY = max(maxY, p.y);
    }

    int minXCount = 0, maxXCount = 0;
    int minYCount = 0, maxYCount = 0;
    int minXIndex = -1, maxXIndex = -1;
    int minYIndex = -1, maxYIndex = -1;
    int interiorCount = 0, interiorIndex = -1;

    for (int i = 0; i < total; ++i) {
        const Point& p = points[i];

        if (p.x == minX) {
            ++minXCount;
            minXIndex = i;
        }
        if (p.x == maxX) {
            ++maxXCount;
            maxXIndex = i;
        }
        if (p.y == minY) {
            ++minYCount;
            minYIndex = i;
        }
        if (p.y == maxY) {
            ++maxYCount;
            maxYIndex = i;
        }

        if (p.x != minX && p.x != maxX &&
            p.y != minY && p.y != maxY) {
            ++interiorCount;
            interiorIndex = i;
        }
    }

    vector<int> candidates;

    auto addCandidate = [&](int index) {
        if (index < 0)
            return;
        if (find(candidates.begin(), candidates.end(), index) ==
            candidates.end()) {
            candidates.push_back(index);
        }
    };

    if (minXCount == 1) addCandidate(minXIndex);
    if (maxXCount == 1) addCandidate(maxXIndex);
    if (minYCount == 1) addCandidate(minYIndex);
    if (maxYCount == 1) addCandidate(maxYIndex);
    if (interiorCount == 1) addCandidate(interiorIndex);

    for (int candidate : candidates) {
        int left = INT_MAX, right = INT_MIN;
        int bottom = INT_MAX, top = INT_MIN;

        for (int i = 0; i < total; ++i) {
            if (i == candidate)
                continue;

            left = min(left, points[i].x);
            right = max(right, points[i].x);
            bottom = min(bottom, points[i].y);
            top = max(top, points[i].y);
        }

        int leftCount = 0, rightCount = 0;
        int bottomCount = 0, topCount = 0;
        bool valid = true;

        for (int i = 0; i < total; ++i) {
            if (i == candidate)
                continue;

            const Point& p = points[i];

            if (p.x == left) ++leftCount;
            if (p.x == right) ++rightCount;
            if (p.y == bottom) ++bottomCount;
            if (p.y == top) ++topCount;

            bool onVertical =
                (p.x == left || p.x == right) &&
                p.y >= bottom && p.y <= top;

            bool onHorizontal =
                (p.y == bottom || p.y == top) &&
                p.x >= left && p.x <= right;

            if (!onVertical && !onHorizontal) {
                valid = false;
                break;
            }
        }

        const Point& removed = points[candidate];

        bool removedOnVertical =
            (removed.x == left || removed.x == right) &&
            removed.y >= bottom && removed.y <= top;

        bool removedOnHorizontal =
            (removed.y == bottom || removed.y == top) &&
            removed.x >= left && removed.x <= right;

        if (valid &&
            !removedOnVertical &&
            !removedOnHorizontal &&
            leftCount >= n &&
            rightCount >= n &&
            bottomCount >= n &&
            topCount >= n) {
            cout << removed.x << ' ' << removed.y << '\n';
            return 0;
        }
    }

    return 0;
}

