    const int total = 4 * n + 1;
    vector<Point> points(total);
    vector<int> xs, ys;
    xs.reserve(total);
    ys.reserve(total);

    for (Point& p : points) {
        cin >> p.x >> p.y;
        xs.push_back(p.x);
        ys.push_back(p.y);
    }

    sort(xs.begin(), xs.end());
    sort(ys.begin(), ys.end());
    xs.erase(unique(xs.begin(), xs.end()), xs.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());

    vector<int> leftCandidates, rightCandidates;
    vector<int> bottomCandidates, topCandidates;

    for (int i = 0; i < min<int>(2, xs.size()); ++i)
        leftCandidates.push_back(xs[i]);
    for (int i = max<int>(0, xs.size() - 2); i < (int)xs.size(); ++i)
        rightCandidates.push_back(xs[i]);

    for (int i = 0; i < min<int>(2, ys.size()); ++i)
        bottomCandidates.push_back(ys[i]);
    for (int i = max<int>(0, ys.size() - 2); i < (int)ys.size(); ++i)
        topCandidates.push_back(ys[i]);

    for (int left : leftCandidates) {
        for (int right : rightCandidates) {
            if (left > right) continue;

            for (int bottom : bottomCandidates) {
                for (int top : topCandidates) {
                    if (bottom > top) continue;

                    int leftCount = 0, rightCount = 0;
                    int bottomCount = 0, topCount = 0;
                    int outsideIndex = -1;
                    bool valid = true;

                    for (int i = 0; i < total; ++i) {
                        const Point& p = points[i];

