                            p.y >= bottom && p.y <= top;

                        bool onHorizontal =
                            (p.y == bottom || p.y == top) &&
                            p.x >= left && p.x <= right;

                        if (!onVertical && !onHorizontal) {
                            if (outsideIndex != -1) {
                                valid = false;
                                break;
                            }
                            outsideIndex = i;
                            continue;
                        }

                        if (p.x == left) ++leftCount;
                        if (p.x == right) ++rightCount;
                        if (p.y == bottom) ++bottomCount;
                        if (p.y == top) ++topCount;
                    }

                    if (valid && outsideIndex != -1 &&
                        leftCount >= n && rightCount >= n &&
                        bottomCount >= n && topCount >= n) {
                        cout << points[outsideIndex].x << ' '
                             << points[outsideIndex].y << '\n';
                        return 0;
                    }
                }
