    for (auto& point : points) {
        cin >> point.x >> point.y;
        xs.push_back(point.x);
        ys.push_back(point.y);
    }

    sort(xs.begin(), xs.end());
    xs.erase(unique(xs.begin(), xs.end()), xs.end());

    sort(ys.begin(), ys.end());
    ys.erase(unique(ys.begin(), ys.end()), ys.end());

    vector<ll> leftCandidates, rightCandidates;
    vector<ll> downCandidates, upCandidates;

    for (int i = 0; i < min<int>(2, xs.size()); ++i)
        leftCandidates.push_back(xs[i]);
    for (int i = max(0, static_cast<int>(xs.size()) - 2);
         i < static_cast<int>(xs.size()); ++i)
        rightCandidates.push_back(xs[i]);

    for (int i = 0; i < min<int>(2, ys.size()); ++i)
        downCandidates.push_back(ys[i]);
    for (int i = max(0, static_cast<int>(ys.size()) - 2);
         i < static_cast<int>(ys.size()); ++i)
        upCandidates.push_back(ys[i]);

    int answer = total;

    for (ll xl : leftCandidates) {
        for (ll xr : rightCandidates) {
            if (xl > xr) continue;

            for (ll yd : downCandidates) {
                for (ll yu : upCandidates) {
                    if (yd > yu) continue;

                    int badIndex = -1;
                    int badCount = 0;
                    int nxl = 0, nxr = 0, nyd = 0, nyu = 0;

                    for (int i = 0; i < total; ++i) {
                        const ll x = points[i].x;
                        const ll y = points[i].y;

